use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl VisitMut for ProcessAuditTransformer { fn visit_expr_mut (& mut self , expr : & mut Expr) { match expr { Expr :: Call (call) => { if let Expr :: Path (path_expr) = & * call . func { let path_str = quote ! (# path_expr) . to_string () ; if path_str . contains ("std::process::Command") || path_str . contains ("Command::new") || path_str . contains ("execute") { let original = call . clone () ; let new_call = quote ! { audit_execute ! (# original) } ; if let Ok (new_expr) = syn :: parse2 :: < Expr > (new_call) { * expr = new_expr ; return ; } } } } Expr :: MethodCall (method_call) => { let method_name = method_call . method . to_string () ; if method_name == "execute" || method_name == "spawn" || method_name == "output" { let original = method_call . clone () ; let new_call = quote ! { audit_execute ! (# original) } ; if let Ok (new_expr) = syn :: parse2 :: < Expr > (new_call) { * expr = new_expr ; return ; } } } _ => { } } syn :: visit_mut :: visit_expr_mut (self , expr) ; } }
}